{"path":"frontend/src/agent/hooks/useAgentChat.ts","content":"/**
 * Chatty — useAgentChat hook.
 *
 * Streams chat responses via SSE. Handles text, tool_start, tool_args,
 * tool_end, confirm, plan_ready, usage, report, title_update, done, error events.
 *
 * Supports 3-tier tool mode (read-only / normal / power) with confirmation flow,
 * plan mode, training/improve modes, and context usage tracking.
 *
 * Performance: rAF-batched text deltas, tail-update pattern for message state,
 * messagesRef for stable closures.
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { getToken } from '../../core/auth/tokenUtils';
import type { ContextUsage } from '../../core/types';

function uuid(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

export type ToolMode = 'read-only' | 'normal' | 'power';
export type ModelTier = 'auto' | 'top' | 'mid' | 'light';
export type TrainingType = 'topic' | 'improve' | null;

export interface ToolCallInfo {
  tool: string;
  toolUseId: string;
  status: 'running' | 'done' | 'error';
  args?: Record<string, unknown>;
  description?: string;
  result?: unknown;
  elapsedMs?: number;
  durationMs?: number;
  startedAt: number;
}

export interface PendingConfirmation {
  tool: string;
  args: Record<string, unknown>;
  toolUseId: string;
  // DB id of the pending assistant row, echoed back on approval so the backend
  // reconciles the exact row even when a provider reuses tool ids (Gemini).
  msgId?: string;
  status: 'pending' | 'approved' | 'denied';
  description?: string;
}

export interface PendingPlan {
  plan: string;
  status: 'pending' | 'approved' | 'iterating';
}

export interface InlineReport {
  id: string;
  title: string;
  subtitle?: string;
  sections: unknown[];
  created_at: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
  toolCalls?: ToolCallInfo[];
  isStreaming?: boolean;
  attachments?: { name: string; size: number }[];
  hidden?: boolean;
  pendingConfirm?: PendingConfirmation;
  pendingPlan?: PendingPlan;
  reports?: InlineReport[];
  model?: string;
  tier?: string;
  playbook?: { slug: string; name: string };
  compacted?: boolean;  // context was compacted just before this turn's response
  // Live audio-transcription progress (pre-stream phase of an upload turn).
  // Not persisted — present only while/after this session's turn streamed.
  transcription?: { filename: string; stage: string; message: string; percent: number | null };
}

// ContextUsage lives in core/types as the single source of truth; re-exported
// here so existing importers (AgentChatPanel) keep their import path.
export type { ContextUsage };

// Insert an out-of-band message (live-meeting coach nudge) into the list.
// Pure and exported for tests. Duplicate ids are dropped (SSE replay ×
// history reload overlap); if the tail is mid-stream the message goes just
// before it — every streaming writer targets prev[prev.length-1], so
// appending would corrupt the in-flight reply.
export function insertMessage(list: ChatMessage[], msg: ChatMessage): ChatMessage[] {
  if (list.some(m => m.id === msg.id)) return list;
  const last = list[list.length - 1];
  if (last?.isStreaming) {
    return [...list.slice(0, -1), msg, last];
  }
  return [...list, msg];
}

interface Options {
  onTitleUpdate?: (convId: string, title: string) => void;
  onImportComplete?: (newConversationId: string) => void;
  onOnboardingComplete?: () => void;
}

export function useAgentChat(apiPrefix: string, options?: Options) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [trainingMode, setTrainingModeState] = useState(false);
  const [trainingType, setTrainingType] = useState<TrainingType>('topic');
  const [planMode, setPlanModeState] = useState(false);
  const [toolMode, setToolMode] = useState<ToolMode>('normal');
  const [contextUsage, setContextUsage] = useState<ContextUsage | null>(null);
  const [greetingPending, setGreetingPending] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const streamInIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  useEffect(() => () => {
    if (streamInIntervalRef.current) clearInterval(streamInIntervalRef.current);
  }, []);
  const savedToolModeRef = useRef<ToolMode>('normal');
  const savedToolModeForPlanRef = useRef<ToolMode>('normal');
  const trainingKickoffRef = useRef(false);
  const trainingKickoffMessageRef = useRef('Hey there!');

  // Stable ref for messages — avoids stale closures in sendMessage
  const messagesRef = useRef<ChatMessage[]>([]);
  useEffect(() => { messagesRef.current = messages; }, [messages]);

  // ── rAF text batching ─────────────────────────────────────────────
  const pendingTextRef = useRef('');
  const rafIdRef = useRef<number | null>(null);

  const flushPendingText = useCallback(() => {
    rafIdRef.current = null;
    const chunk = pendingTextRef.current;
    if (!chunk) return;
    pendingTextRef.current = '';
    setMessages(prev => {
      if (!prev.length) return prev;
      const last = prev[prev.length - 1];
      if (last.role !== 'assistant') return prev;
      return [...prev.slice(0, -1), { ...last, content: last.content + chunk }];
    });
  }, []);

  const scheduleFlush = useCallback(() => {
    if (rafIdRef.current !== null) return;
    rafIdRef.current = requestAnimationFrame(flushPendingText);
  }, [flushPendingText]);

  // ── Tail-update helper ────────────────────────────────────────────
  const updateLastAssistant = useCallback(
    (updater: (msg: ChatMessage) => ChatMessage) => {
      setMessages(prev => {
        if (!prev.length) return prev;
        const last = prev[prev.length - 1];
        if (last.role !== 'assistant') return prev;
        return [...prev.slice(0, -1), updater(last)];
      });
    },
    []
  );

  const sendMessage = useCallback(async (text: string, files?: File[], approvedTool?: {
    tool: string;
    args: Record<string, unknown>;
    toolUseId: string;
    msgId?: string;
    result: unknown;
  }, overrides?: {
      tool_mode?: string;
      plan_mode?: boolean;
      hidden?: boolean;
      playbook?: { slug: string; name: string };
      continuation_resume?: boolean;
      conversation_id?: string;
    }) => {
    const playbook = overrides?.playbook;
    // The [playbook:slug] marker rides in the persisted content (like the
    // "[via Telegram from X]" prefix) so the reference survives history
    // reloads; the payload field below triggers this turn's expansion.
    const continuationResume = overrides?.continuation_resume === true;
    const content = playbook ? `[playbook:${playbook.slug}] ${text}`.trimEnd() : text;
    const userMsg: ChatMessage = {
      id: uuid(),
      role: 'user',
      content,
      timestamp: Date.now(),
      attachments: files?.map(f => ({ name: f.name, size: f.size })),
      hidden: overrides?.hidden,
      playbook,
    };
    const assistantMsg: ChatMessage = {
      id: uuid(),
      role: 'assistant',
      content: '',
      timestamp: Date.now(),
      toolCalls: [],
      isStreaming: true,
    };

    setMessages(prev =>
      continuationResume
        ? [...prev, assistantMsg]
        : [...prev, userMsg, assistantMsg]
    );
    setIsStreaming(true);

    // Server-side assembly: the backend rebuilds the full conversation from the
    // DB by conversation_id (with full tool results), so send ONLY the new
    // message — not the whole transcript. For an approved write tool the new
    // message is the "[Approved] <tool>" marker, which the backend reconciles
    // onto the pending row rather than persisting as a user turn.
    const history = continuationResume
      ? []
      : [{ role: userMsg.role, content: userMsg.content }];

    // Effective tool mode: training forces power
    const effectiveMode = overrides?.tool_mode ?? (trainingMode ? 'power' : toolMode);

    abortRef.current = new AbortController();

    try {
      const token = getToken();
      const hasFiles = files && files.length > 0;

      const payload: Record<string, unknown> = {
        messages: history,
        training_mode: trainingMode,
        training_type: trainingType,
        conversation_id: overrides?.conversation_id ?? conversationId,
        tool_mode: effectiveMode,
        plan_mode: overrides?.plan_mode ?? planMode,
        continuation_resume: continuationResume,
      };
      if (approvedTool) payload.approved_tool = approvedTool;
      if (playbook) payload.playbook_slug = playbook.slug;

      let res: Response;
      if (hasFiles) {
        const formData = new FormData();
        formData.append('payload', JSON.stringify(payload));
        for (const f of files) {
          formData.append('files', f);
        }
        res = await fetch(`${apiPrefix}/chat/upload`, {
          method: 'POST',
          headers: {
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
          body: formData,
          signal: abortRef.current.signal,
        });
      } else {
        res = await fetch(`${apiPrefix}/chat`, {
