  provider_override?: string;
}

type Tab = 'chat' | 'knowledge'| 'project' | 'playbooks' | 'reports' | 'reminders' | 'heartbeat';

function parseTab(raw: string | null): Tab | null {
  if (!raw) return null;
  if (raw === 'activity') return 'heartbeat';
  if (['chat', 'knowledge', 'playbooks', 'reports', 'reminders', 'heartbeat'].includes(raw)) return raw as Tab;
  return null;
}

const TABS: { key: Tab; labelKey: string }[] = [
  { key: 'chat', labelKey: 'agentPage.tabs.chat' },
  { key: 'knowledge', labelKey: 'agentPage.tabs.knowledge' },
  { key: 'project', labelKey: 'agentPage.tabs.project' },
  { key: 'playbooks', labelKey: 'agentPage.tabs.playbooks' },
  { key: 'reports', labelKey: 'agentPage.tabs.reports' },
