  const [activeTab, setActiveTab] = useState<Tab>(() => parseTab(searchParams.get('tab')) || 'chat');
  const [showAvatarPicker, setShowAvatarPicker] = useState(false);
  const [avatarMenuRect, setAvatarMenuRect] = useState<DOMRect | null>(null);
  const [showSidebar, setShowSidebar] = useState(false);
  const [openaiAvailable, setOpenaiAvailable] = useState(false);
  const [alwaysPowerMode, setAlwaysPowerMode] = useState(false);
  const [avatarCacheBust, setAvatarCacheBust] = useState(0);
  const [activeProvider, setActiveProvider] = useState('');
  const [modelTier, setModelTier] = useState<ModelTier>('auto');
  const [tierLabels, setTierLabels] = useState<Record<string, string>>({});
  const [globalModelTier, setGlobalModelTier] = useState<ModelTier>('auto');
  const isMobile = useIsMobile();
  const prevOnboardingComplete = useRef<boolean | null>(null);

  const apiPrefix = `/api/agents/${agentId}`;
  const convs = useConversations(apiPrefix);
  const pb = usePlaybooks(apiPrefix);

  const handleTitleUpdate = useCallback((convId: string, title: string) => {
    convs.updateConversationTitle(convId, title);
    convs.loadConversations();
  }, [convs]);

  const importCompleteRef = useRef<((id: string) => void) | null>(null);
  const onboardingCompleteRef = useRef<(() => void) | null>(null);

  const chat = useAgentChat(apiPrefix, {
    onTitleUpdate: handleTitleUpdate,
    onImportComplete: (id) => importCompleteRef.current?.(id),
    onOnboardingComplete: () => onboardingCompleteRef.current?.(),
  });

  // Live meeting recorder + coach. The hook reads these callbacks through a
  // per-render ref, so fresh chat/convs closures are always used.
  const live = useLiveMeeting(apiPrefix, {
    conversationId: chat.conversationId,
    onCoachMessage: (msg, sessConvId) => {
      if (chat.conversationId === sessConvId) chat.appendMessage(msg);
      // Other conversations: the nudge is persisted server-side and loads
      // normally when that conversation is opened.
    },
    onSessionConversation: async (convId) => {
      if (chat.conversationId === convId) return;
      if (!chat.conversationId) {
        chat.adoptConversation(convId);
        convs.loadConversations();
        return;
      }
      // Reattach while a different conversation is open → switch to the
      // meeting conversation (same flow as the import redirect above).
      await convs.loadConversations();
      const msgs = await convs.selectConversation(convId);
      if (msgs) chat.loadMessages(msgs, convId);
    },
    onSessionEnded: async (sessConvId) => {
      if (chat.conversationId !== sessConvId || chat.isStreaming) return;
      const msgs = await convs.selectConversation(sessConvId);
      if (msgs) chat.loadMessages(msgs, sessConvId);
    },
  });

  useEffect(() => {
    importCompleteRef.current = async (newConversationId: string) => {
      await convs.loadConversations();
      const msgs = await convs.selectConversation(newConversationId);
      if (msgs) chat.loadMessages(msgs, newConversationId);
    };
    onboardingCompleteRef.current = () => {
      if (agentId) api<AgentRow>(`/api/agents/${agentId}`).then(a => { setAgent(a); chat.setTrainingMode(false); }).catch(() => { chat.setTrainingMode(false); });
    };
  }); // intentionally no deps — always tracks latest convs/chat

  const scrollRef = useRef<HTMLDivElement>(null);
  const restoredConversationRef = useRef<string | null>(null);
  const topBarVisible = useScrollDirection(scrollRef);

  useEffect(() => {
    if (!agentId) return;
    localStorage.setItem('chatty_last_agent', agentId);
    api<AgentRow>(`/api/agents/${agentId}`)
      .then(a => {
        setAgent(a);
        if (a.model_tier) setModelTier(a.model_tier as ModelTier);
      })
      .catch(() => navigate('/'));
  }, [agentId, navigate]);

  useEffect(() => {
    if (!agentId) return;
    api<{ generate_available: boolean }>(`/api/agents/${agentId}/avatar/availability`)
      .then(d => setOpenaiAvailable(d.generate_available))
      .catch(() => {}); // best-effort: hides "Generate with AI" when unknown
  }, [agentId]);

  useEffect(() => {
    api<ProviderStatus>('/api/providers')
      .then(p => { setActiveProvider(p.active_provider); })
      .catch(() => {}); // best-effort: tier labels degrade gracefully
  }, []);

  // Fetch tier labels and resolve for the agent's provider
  useEffect(() => {
    if (!agent) return;
    const providerKey = agent.provider_override || activeProvider;
    if (!providerKey) return;
    api<{ tier_labels: Record<string, Record<string, string>> }>('/api/providers/tiers')
      .then(d => setTierLabels(d.tier_labels[providerKey] || {}))
      .catch(() => {}); // best-effort: tier labels degrade gracefully
  }, [agent, activeProvider]);


