      try {
        const res = await api<{ alerts: AgentAlert[] }>(`/api/alerts?agent=${agentSlug}`);
        if (!cancelled) setAlerts(res.alerts);
      } catch { /* alerts are supplementary */ }
    })();
    return () => { cancelled = true; };
  }, [agentSlug]);
